ALTER TABLE "campaigns" ADD COLUMN "ladder" jsonb;--> statement-breakpoint
-- Campaigns already started from The Empty Crown get its Dominion ladder (no stage yet; the narrator sets it).
UPDATE "campaigns" SET "ladder" = '{"title":"Dominion","unranked":"No realm yet","condition":"Your Realm","stages":[{"name":"Holding","summary":"One place that is yours (a hall, a village, a keep, or a harbor) and people who follow you."},{"name":"Lordship","summary":"Several settlements, a steady food supply, armed defenders, and laws you enforce, and it has survived a winter."},{"name":"Domain","summary":"A real territory across much of the Reach, a seat, a banner, and a claim others must answer."},{"name":"Kingdom","summary":"Recognized as a crown by at least two of the five powers, or held so firmly that no one can deny it."}],"current":null}'::jsonb WHERE "ladder" IS NULL AND "world_bible" LIKE '# The Empty Crown%';
